static Car newCar(int m, int lo, int hi) {
  Car c;
  memset(&c, 0, sizeof c);
  c.model = m;
  c.col[0] = MOD[m].r; c.col[1] = MOD[m].g; c.col[2] = MOD[m].b;
  for (int i = 0; i < NP; i++) c.cond[i] = lo + rand() % (hi - lo + 1);
  c.fuel = (float)(50 + rand() % 51);
  c.oil = (float)(45 + rand() % 56);
  c.filt = (float)(45 + rand() % 56);
  c.bfl = (float)(45 + rand() % 56);
  c.pads = (float)(45 + rand() % 56);
  c.disc = (float)(50 + rand() % 51);
  c.tires = (float)(45 + rand() % 56);
  c.bal = (float)(50 + rand() % 51);
  return c;
}
static int avgc(const Car &c) { int s = 0; for (int i = 0; i < NP; i++) s += c.cond[i]; return s / NP; }
static int carValue(const Car &c) {
  float k = 0;
  for (int i = 0; i < NP; i++) k += PW[i] * c.cond[i] / 100.0f;
  float v = MOD[c.model].base * (0.15f + 0.85f * k) * (1.0f + 0.12f * c.tune) * (1.0f - c.dirt * 0.0015f) * (0.9f + 0.03f * c.oil / 100.0f + 0.015f * c.filt / 100.0f + 0.015f * c.bfl / 100.0f + 0.01f * c.pads / 100.0f + 0.005f * c.disc / 100.0f + 0.02f * c.tires / 100.0f + 0.005f * c.bal / 100.0f);
  return (int)v;
}
static const float PART_K = 0.45f;                       // цена новой детали = база машины * вес детали * PART_K (раньше 0.6)
static int itemBase(int kind, int model);               // цена детали/расходника (определена ниже)
static int partPrice(const Car &c, int p) { return itemBase(p, c.model); }
static int repairCost(const Car &c, int p) {            // ремонт = замена новой деталью: цена детали + работа (10%)
  if (c.cond[p] >= 85) return -1;
  int np = itemBase(p, c.model);
  return np + imax(5, np / 10);
}
static int salePrice(const Car &c) { return (int)(carValue(c) * pmult); }
static int TANKL[NMODEL] = {40, 45, 50, 55, 60, 65, 70, 75, 80, 70, 75, 80, 60, 70, 96, 93, 110, 64, 75, 39, 42, 65, 70, 96, 43, 63, 55, 100, 70, 60, 50, 65, 70, 70, 93, 80, 90, 82, 75, 55, 74, 70, 70, 70, 80, 80};   // Марк 2 - 70 л, Крузер 100 - 96 л, Крузер 200 - 93 л   // объём бака, л
static bool modelRemoved(int m) { return m == 14 || m == 16 || m == 18 || m == 22 || m == 45; }   // убраны из игры: Ланд Крузер 100, Ланд Крузер 300, Альфард, Супра A80 (обычная) и Супра гоночная A80
static int pickModel() {
  int w[NMODEL] = {20, 17, 13, 12, 7, 5, 4, 2, 2, 8, 6, 6, 4, 6, 4, 3, 2, 1, 3, 12, 8, 2, 2, 1, 10, 2, 2, 1, 1, 2, 7, 6, 3, 1, 3, 2, 1, 1, 1, 6, 1, 1, 1, 1, 1, 1}, t = 0;
  for (int k = 0; k < NCUSTOM; k++) w[NBASE + k] = gObjOf[NBASE + k] >= 0 ? 3 : 0;      // свои модели появляются в продаже, если загружены
  for (int i = 0; i < NMODEL; i++) if (modelRemoved(i)) w[i] = 0;
  for (int i = 0; i < NMODEL; i++) t += w[i];
  int r = rand() % t;
  for (int i = 0; i < NMODEL; i++) { if (r < w[i]) return i; r -= w[i]; }
  return 0;
}
static void genMarket() {
  market.clear();
  for (int i = 0; i < 24; i++) {                  // на рынке 24 машины в день: среди них можно искать по модели, состоянию и цене
    Car c = newCar(pickModel(), 15, 75);
    c.dirt = (float)(rand() % 70);
    c.ask = (int)(carValue(c) * frand(0.6f, 0.85f));
    market.push_back(c);
  }
  mIdx = 0; dPos = 0;
}
static void genOrder(Order &o) {
  o.nameIdx = rand() % 6;
  o.type = 0;
  if (rand() % 100 < 45) {                       // клиент хочет купить определённую марку
    static const int mins[4] = {40, 55, 70, 85};
    o.type = 1;
    o.buy.nameIdx = o.nameIdx;
    o.buy.model = pickModel();
    o.buy.minAvg = mins[rand() % 4];
    o.buy.dest = rand() % 4;
    o.buy.price = (int)(MOD[o.buy.model].base * (0.15f + 0.85f * o.buy.minAvg / 100.0f) * frand(1.15f, 1.4f));
    o.car = newCar(o.buy.model, 50, 60);
    o.car.dest = o.buy.dest;
    return;
  }
  Car c = newCar(pickModel(), 55, 95);
  c.client = 1; c.nameIdx = o.nameIdx; c.dest = rand() % 4; c.dirt = (float)(40 + rand() % 50);
  int n = 1 + rand() % 3, mask = 0;
  for (int i = 0; i < n; i++) { int p = rand() % NP; mask |= 1 << p; c.cond[p] = 15 + rand() % 45; }
  int rw = 80;
  for (int p = 0; p < NP; p++) if (mask & (1 << p)) rw += (int)(repairCost(c, p) * 1.45f) + 25;     // деталь + работа с запасом ~45%, чтобы заказ не уходил в минус даже при дорогих запчастях
  {
    static const int chance[NEX] = {55, 30, 25, 20, 15, 20, 15}, bonus[NEX] = {90, 70, 80, 70, 110, 120, 60};
    int cnt = 0, em = 0;
    for (int k = 0; k < NEX; k++) if (rand() % 100 < chance[k]) { em |= 1 << k; cnt++; }
    for (int k = NEX - 1; k >= 0 && cnt > 3; k--) if (em & (1 << k)) { em &= ~(1 << k); cnt--; }
    for (int k = 0; k < NEX; k++)
      if (em & (1 << k)) { mask |= EXBIT[k]; exSet(c, k, (float)(4 + rand() % 36)); rw += bonus[k]; }
  }
  c.mask = mask;
  c.reward = rw;
  o.car = c;
}
static int svcSel = 0;   // подвкладка сервиса
static void genOrders() { for (int i = 0; i < 3; i++) genOrder(orders[i]); oSel = 0; }

