// ---------- Запчасти: склад и доставка ----------
enum { NK = 12 };
static const char *ITN[NK] = {"Двигатель", "Тормоза", "Подвеска", "Колёса", "Кузов", "Выхлоп",
                              "Масло", "Фильтр", "Торм. жидкость", "Колодки", "Диски", "Шины"};
static float OILCAP[NMODEL] = {3.5f, 4.0f, 4.5f, 4.5f, 5.0f, 5.5f, 5.5f, 6.0f, 6.5f, 5.5f, 6.0f, 6.0f, 4.5f, 5.0f, 7.0f, 7.5f, 7.5f, 8.0f, 6.0f, 3.75f, 3.75f, 4.8f, 5.0f, 8.5f, 3.5f, 6.5f, 4.5f, 8.5f, 4.5f, 4.5f, 3.5f, 5.0f, 5.0f, 8.0f, 8.0f, 7.5f, 7.5f, 8.5f, 8.5f, 3.5f, 10.0f, 4.5f, 4.5f, 4.5f, 4.8f, 5.0f};
struct StockItem { int kind, model, qty; };
struct PartOrder { int kind, model; float eta, total; };
static std::vector<StockItem> stock;
static std::vector<PartOrder> shipping;
static float partMult = 1.0f;         // цена запчастей сегодня
static int itemBase(int kind, int model) {
  const ModelInfo &m = MOD[clampi(model, 0, NMODEL - 1)];
  if (kind < NP) return imax(10, (int)(m.base * PW[kind] * PART_K));
  switch (kind) {
    case 6: return (int)ceilf(OILCAP[clampi(model, 0, NMODEL - 1)] * 12.0f);
    case 7: return 20 + m.base / 500;
    case 8: return 20 + m.base / 1500;
    case 9: return 25 + m.base / 400;
    case 10: return 40 + m.base / 250;
    default: return 60 + m.base / 120;
  }
}
static int itemPrice(int kind, int model) { return imax(5, (int)(itemBase(kind, model) * partMult)); }
static int stockGet(int kind, int model) {
  for (size_t i = 0; i < stock.size(); i++) if (stock[i].kind == kind && stock[i].model == model) return stock[i].qty;
  return 0;
}
static void stockAdd(int kind, int model, int n) {
  for (size_t i = 0; i < stock.size(); i++) if (stock[i].kind == kind && stock[i].model == model) { stock[i].qty += n; return; }
  StockItem it; it.kind = kind; it.model = model; it.qty = n;
  stock.push_back(it);
}
static bool stockUse(int kind, int model) {
  for (size_t i = 0; i < stock.size(); i++)
    if (stock[i].kind == kind && stock[i].model == model && stock[i].qty > 0) {
      if (--stock[i].qty == 0) stock.erase(stock.begin() + i);
      return true;
    }
  return false;
}
static void updateShipping(float dt) {
  for (size_t i = 0; i < shipping.size();) {
    shipping[i].eta -= dt;
    if (shipping[i].eta <= 0) {
      char m[110];
      snprintf(m, sizeof m, "ДОСТАВЛЕНО: %s (%s)", ITN[shipping[i].kind], MOD[shipping[i].model].name);
      stockAdd(shipping[i].kind, shipping[i].model, 1);
      shipping.erase(shipping.begin() + i);
      say(m);
    } else i++;
  }
}

